#include <set>
#include <iostream>

template<typename T>
struct RuntimeCmp {
    enum mode_t { normal, reverse };
    mode_t mode = normal;
    RuntimeCmp(mode_t m = normal) : mode(m) {}
    bool operator()(const T& a, const T& b) const { return (mode == normal) ? (a < b) : (a > b); }
    bool operator==(const RuntimeCmp& other) const { return mode == other.mode; }
};

using IntSet = std::set<int, RuntimeCmp<int>>;

int main() {
    RuntimeCmp<int> reverse_cfg(RuntimeCmp<int>::reverse);
    IntSet coll2(reverse_cfg); 
    coll2.insert(10); 

    IntSet coll1; // Starts with normal ordering
    coll1.insert(1); 

    coll1 = coll2; // Assignment copies elements AND comparator
    coll1.insert(15);

    // coll1 now uses reverse ordering (15 > 10 > 1)
    for (int x : coll1) std::cout << x << " "; 
    // Output: 15 10 1 
}
